def _as_history(history):
    """The past as a DataFrame: one row per time step, one column per series.

    A list or NumPy array has no time labels, so its rows are labelled 0, 1,
    2, ... and its columns ``y`` (one series) or 0, 1, ... (several series).
    """
    if isinstance(history, pd.DataFrame):
        return history
    if isinstance(history, pd.Series):
        return history.to_frame(name=history.name if history.name is not None else "y")
    if isinstance(history, (list, tuple, np.ndarray)):
        values = np.asarray(history)
        if values.ndim == 1:
            return pd.DataFrame({"y": values})
        if values.ndim == 2:
            return pd.DataFrame(values)
    raise TypeError(
        "history must be a pandas DataFrame or Series, a list, or a one- or two-dimensional "
        "NumPy array"
    )


def _one_value_per_step(values, names):
    """Read one value per step as one row per step when there is a single series."""
    try:
        array = np.asarray(values)
    except (TypeError, ValueError):
        return values  # ragged or non-numeric: the output checks report it
    if array.ndim == 1 and names is not None and len(names) == 1:
        return array[:, None]
    return array


def _as_forecast(output, task):
    """Turn whatever the model's ``predict`` returned into a Forecast to check.

    - A list or NumPy array holds one value per step for one series, or one
      row per step and one column per series. Its rows are the requested
      future steps in order and its columns the history's series in order.
    - A pandas DataFrame or Series keeps its own index and column names, so
      wrong dates or a wrong series order still fail their checks. An unnamed
      Series stands for the task's single series.
    - A Forecast is used as given. Without ``target_names`` its series are the
      task's, and a one-dimensional ``point`` for one series is one value per step.
    """
    if isinstance(output, Forecast):
        names = (
            task.target_names if output.target_names is None else output.target_names
        )
        point = output.point
        if point is not None:
            point = _one_value_per_step(point, names)
        if names is output.target_names and point is output.point:
            return output
        return dataclasses.replace(output, point=point, target_names=names)
    if isinstance(output, pd.Series):
        if output.name is None and len(task.target_names) == 1:
            names = task.target_names
        else:
            names = (output.name if output.name is not None else "y",)
        return Forecast(
            output.index, point=output.to_numpy()[:, None], target_names=names
        )
    if isinstance(output, pd.DataFrame):
        return Forecast(
            output.index, point=output.to_numpy(), target_names=tuple(output.columns)
        )
    if isinstance(output, (list, tuple, np.ndarray)):
        return Forecast(
            task.future_index.copy(),
            point=_one_value_per_step(output, task.target_names),
            target_names=task.target_names,
        )
    raise TypeError(
        "model.predict(future_index) must return one value per future step: a list or NumPy "
        "array, a pandas Series or DataFrame indexed by future_index, or a timegym.Forecast; "
        f"got {type(output).__name__}"
    )


def _instance_seeds(seeds, seed, instances, default_instances):
    """Return the case seeds and the seeding record for run metadata.

    With an explicit ``seeds`` list nothing else is derived. Otherwise
    instance ``i`` uses ``seed + i``; ``seed=None`` draws a fresh base seed,
    which is recorded so the run can be repeated.
    """
    if seeds is not None:
        if seed != 0 or instances is not None:
            raise ValueError("Pass either seeds=[...] or seed/instances, not both")
        return [nonnegative_int(value, "seed") for value in seeds], None
    count = positive_int(
        default_instances if instances is None else instances, "instances"
    )
    base = secrets.randbelow(2**31) if seed is None else nonnegative_int(seed, "seed")
    return [base + i for i in range(count)], {"seed": base, "instances": count}


def _ready_made(cases):
    """Check a list of ready-made cases and return it with each case's label and seed.

    The label is the manifest's ``kind`` (``"case"`` when absent) and the seed
    its ``seed`` (``None`` when absent): real data has neither.
    """
    if isinstance(cases, Case):
        raise TypeError("cases must be a list of Case objects, not one Case")
    cases = list(cases)
    if not cases:
        raise ValueError("Provide at least one case")
    identities = []
    for position, case in enumerate(cases):
        if not isinstance(case, Case):
            raise TypeError(
                f"cases[{position}] is a {type(case).__name__}, not a timegym.Case"
            )
        if not isinstance(case.manifest, dict):
            raise TypeError(f"cases[{position}].manifest must be a dictionary")
        label = case.manifest.get("kind", "case")
        if not isinstance(label, str) or not label:
            raise ValueError(
                f"cases[{position}].manifest['kind'] must be a nonempty string"
            )
        seed = case.manifest.get("seed")
        if seed is not None:
            seed = nonnegative_int(seed, f"cases[{position}].manifest['seed']")
        identities.append((label, seed))
    return cases, identities


def _evaluate_case(
    case,
    make_forecast,
    label,
    seed,
    dependence_seed,
    settings,
    metrics=None,
    checks=None,
):
    """Forecast one case with ``make_forecast(case)``, then check the forecast and measure its errors.

    Returns ``(forecast, result)``. An exception from the model, or from
    reading its output, becomes the case's ``model_execution`` error, so one
    broken case does not stop the run; ``forecast`` is then ``None`` when no
    forecast was made.
    """
    forecast = None
    try:
        forecast = make_forecast(case)
        result = _evaluate_forecast(
            case,
            forecast,
            check_dependence=settings["check_dependence"],
            dependence_seed=dependence_seed,
            n_calibration=settings["n_calibration"],
            alpha=settings["alpha"],
            requests=_metric_requests(metrics),
            check_requests=_check_requests(checks),
        )
    except Exception as exc:
        result = CaseResult(
            scenario=label,
            seed=seed,
            diagnostics=[
                DiagnosticResult(
                    name="model_execution",
                    status="ERROR",
                    category="execution",
                    message=f"{type(exc).__name__}: {exc}",
                    evidence=exception_evidence(exc),
                )
            ],
            metrics={},
            manifest=case.manifest,
        )
    return forecast, result


def _evaluate_ready_made(cases, make_forecast, settings, metrics=None, checks=None):
    """Evaluate ready-made cases in order; cases with the same label share a row of the plots."""
    cases, identities = _ready_made(cases)
    rows, results = {}, []
    for position, (case, (label, seed)) in enumerate(zip(cases, identities)):
        row = rows.setdefault(label, [len(rows), 0])
        dependence_seed = (position if seed is None else seed) + settings[
            "dependence_seed_offset"
        ]
        forecast, result = _evaluate_case(
            case,
            lambda c: make_forecast(position, c),
            label,
            seed,
            dependence_seed,
            settings,
            metrics,
            checks,
        )
        results.append(
            EvaluatedCase(
                case=case,
                forecast=forecast,
                result=result,
                scenario_index=row[0],
                seed_index=row[1],
            )
        )
        row[1] += 1
    return results


