def _steps_pipeline(steps):
    """scikit-learn's ``make_pipeline(*steps)`` for a list of steps; a list that ends in no regressor is refused."""
    steps = list(steps)
    if not steps or not is_sklearn_regressor(steps[-1]):
        raise ValueError(
            "A list of steps must be scikit-learn estimators ending in a regressor, such as "
            f"[StandardScaler(), Ridge()]; got {steps!r}"
        )
    from sklearn.pipeline import make_pipeline

    return make_pipeline(*steps)


def _old_settings(settings):
    """The diagnostic settings the old plot helpers passed through, with their old defaults."""
    allowed = {
        "check_dependence": False,
        "n_calibration": 99,
        "alpha": 0.05,
        "dependence_seed_offset": 100_000,
    }
    unknown = set(settings) - set(allowed)
    if unknown:
        raise TypeError(f"unexpected keyword arguments: {', '.join(sorted(unknown))}")
    return {**allowed, **settings}


class Pipeline:
    """Evaluate fresh model instances on independent, seeded scenarios.

    The model goes first, as one of:

    - a model: anything with ``fit(history)`` and ``predict(future_index)``,
      copied fresh before every case, even if it can also be called;
    - a list of scikit-learn steps ending in a regressor, such as
      ``[StandardScaler(), Ridge()]``, which becomes one scikit-learn
      pipeline; a scikit-learn pipeline you already have is taken as it is;
    - a class, or a function that returns a fresh model, called for every case,
      as ``Pattern(attainable_by=...)`` takes them.

    The history is the past as a DataFrame, one row per time step and one
    column per series (``y`` for one series). ``future_index`` holds the labels
    of the steps to forecast, continuing the history's index. ``predict``
    returns one value per step: a list or NumPy array (one column per series
    when there are several), a Series or DataFrame indexed by ``future_index``,
    or a Forecast, which can also carry quantiles and samples. A scikit-learn
    regressor forecasts from windows of the last ``window_length`` steps, with
    one of REDUCTIONS; neither setting changes native models. An optional
    ``target_transform`` is refitted on each history before the model and
    inverted on the forecast it returns.

    ``name`` names the model wherever a run shows it: ``Pipeline(model,
    name="Forest")`` titles the scorecard "Forest", heads the run's plots,
    labels it in a comparison and is ``result.metadata["name"]``,
    while ``result.metadata["model"]`` still names the class. The name is
    saved with the pipeline's configuration, so replay keeps it. Without a
    name the scorecard is titled by the model, such as
    ``GaussianAR1Forecaster(...)`` or "StandardScaler + Ridge".

    ``add()`` and ``model_factory=`` still work and warn, and so does a
    pipeline with no model, which tests the last value as ``NaiveForecaster``.
    """

    def __init__(
        self,
        model=None,
        window_length=12,
        reduction="recursive",
        *,
        model_factory=None,
        target_transform=None,
        name=None,
    ):
        if reduction not in REDUCTIONS:
            raise ValueError(
                f"Unknown reduction {reduction!r}; choose from {REDUCTIONS}"
            )
        protocol = ("clone_unfitted", "fit_transform", "inverse_transform")
        if target_transform is not None and (
            inspect.isclass(target_transform)
            or not all(
                callable(getattr(target_transform, name, None)) for name in protocol
            )
        ):
            raise TypeError(
                "target_transform must be an instance implementing clone_unfitted(), "
                "fit_transform(history) and inverse_transform(forecast)"
            )
        name = _checked_name(name)
        if model is not None and model_factory is not None:
            raise ValueError("Specify model or model_factory, not both")
        if model_factory is not None and not callable(model_factory):
            raise TypeError(
                "model_factory must be a callable producing a fresh unfitted model"
            )
        if isinstance(model, (list, tuple)):
            model = _steps_pipeline(model)
        window_length = positive_int(window_length, "window_length")
        if model_factory is not None:
            _warn_deprecated(_FACTORY_MOVED)
        if (
            model is NaiveForecaster
        ):  # the class itself: one warning here, none for each model it makes
            _warn_deprecated(
                "NaiveForecaster is deprecated and will be removed in a later release: use "
                "LastValueForecaster, which makes the same forecasts"
            )
        self.model = model
        self.model_factory = model_factory
        self.window_length = int(window_length)
        self.reduction = reduction
        self.target_transform = target_transform
        self.name = name
        self.steps = []
        self._warned_no_model = False

    def _ask_for_a_model(self):
        """Warn once, when the pipeline is first used, that it has no model and tests the last value."""
        if (
            self.model is None
            and self.model_factory is None
            and not self.steps
            and not getattr(self, "_warned_no_model", False)
        ):
            self._warned_no_model = True
            _warn_deprecated(_NO_MODEL)

    def add(self, estimator, **parameters):
        """Add an sklearn transformer or final regressor and return the pipeline; pass a list of steps instead.

        ``Pipeline(window_length=12).add(StandardScaler()).add(Ridge())`` makes
        the same forecasts as ``Pipeline([StandardScaler(), Ridge()],
        window_length=12)``. ``add`` still works and warns once for each
        pipeline, and will be removed in a later release.
        """
        if self.model is not None or self.model_factory is not None:
            raise ValueError("Use a native model or sklearn steps, not both")
        if not self.steps:
            _warn_deprecated(_ADD_MOVED)
        if inspect.isclass(estimator):
            estimator = estimator(**parameters)
        elif parameters:
            estimator = fresh_model(estimator).set_params(**parameters)
        self.steps.append(estimator)
        return self

    def _model(self, horizon):
        if self.steps:
            return SklearnForecaster(
                self.steps,
                self.window_length,
                reduction=self.reduction,
                horizon=horizon,
            )
        if self.model is None and self.model_factory is None:
            return _naive_without_warning()
        if self.model_factory is not None:
            candidate = self.model_factory()
        elif self.model is NaiveForecaster:
            candidate = _naive_without_warning()
        else:
            # A copy of a model, or a new one from a class or a function: the rule of Pattern(attainable_by=).
            candidate = _fresh_from(self.model)
        if is_sklearn_regressor(candidate) and not callable(
            getattr(candidate, "clone_unfitted", None)
        ):
            return SklearnForecaster(
                [candidate],
                self.window_length,
                reduction=self.reduction,
                horizon=horizon,
            )
        return candidate

    def _model_name(self) -> str:
        if self.steps:
            return "SklearnForecaster"
        if self.model_factory is not None:
            return getattr(self.model_factory, "__qualname__", "model_factory")
        if self.model is None:
            return "NaiveForecaster"
        if inspect.isclass(self.model):
            return self.model.__name__
        if _is_maker(self.model):  # a function that returns a fresh model
            return getattr(self.model, "__qualname__", type(self.model).__name__)
        return _steps_name(self.model) or type(self.model).__name__

    def to_config(self):
        """Return JSON-safe configuration and whether safe automatic replay is supported."""
        self._ask_for_a_model()
        return pipeline_config(self)

    @classmethod
    def from_config(cls, config):
        """Rebuild allowlisted built-in models and target transforms without dynamic imports."""
        return cls(**pipeline_from_config(config))

    @_renamed_keywords(context="history")
    def predict(self, history, future_index):
        """Fit on the history and predict the supplied index, without future targets.

        ``history`` is the past: a DataFrame with one column per series, a
        Series, or a list or NumPy array, whose rows are labelled 0, 1, 2, ...
        ``future_index`` is any sequence of the labels to forecast; after a
        list of 120 values the next 12 steps are ``range(120, 132)``.

        A target transform is refitted on this history alone and the model sees
        only the transformed history. A forecast that meets its contract is
        inverted to the original scale; one that violates it is returned
        unchanged, so evaluation reports the model's fault, not the inversion's.
        The old keyword ``context=`` still works and warns.
        """
        self._ask_for_a_model()
        history = _as_history(history)
        if not isinstance(future_index, pd.Index):
            future_index = pd.Index(future_index)
        # Share the public task contract, including unique target names.
        task = ForecastTask(history=history, future_index=future_index)
        transform = None
        if self.target_transform is not None:
            transform = self.target_transform.clone_unfitted()
            if transform is self.target_transform:
                raise ValueError(
                    "clone_unfitted() must return a new target transform instance"
                )
            task = ForecastTask(
                history=transform.fit_transform(history.copy(deep=True)),
                future_index=future_index,
            )
        model = self._model(len(future_index))
        model.fit(task.history.copy(deep=True))
        forecast = _as_forecast(model.predict(future_index.copy()), task)
        if transform is not None and not forecast.validate(task):
            forecast = transform.inverse_transform(forecast)
        return forecast

    @_renamed_keywords(scores="metrics")
    def run(
        self,
        scenarios=None,
        seeds=None,
        *,
        seed=0,
        instances=None,
        cases=None,
        noise_levels=None,
        history_length=None,
        horizon=None,
        keep_data=False,
        attainable=False,
        interval_level=None,
        metrics=None,
        checks=None,
        **old_arguments,
    ):
        """Forecast every case with a fresh model, check each forecast and measure its errors; return a ForecastRun.

        What to forecast, as the first argument:

        - nothing: the scorecard's ten kinds of series (``timegym.PATTERNS``) at
          low and high noise, 120 steps of history and 24 to forecast;
        - keys of ``timegym.PATTERNS`` such as ``["trend", "seasonal"]``, and
          ``Pattern`` objects of your own beside them: those rows of the
          scorecard. ``noise_levels``, ``history_length`` and ``horizon`` set
          its columns and lengths, as in ``scenario_grid``;
        - ``Scenario`` objects, or anything with ``generate(seed)`` and
          ``kind``: each as it was built, one row of the scorecard each.

        Each is drawn ``instances`` times (10 by default). Draw ``i`` uses seed
        ``seed + i`` in every row, so rows are compared on the same random
        draws. ``seed=None`` picks a fresh base seed and records it in
        ``result.metadata["seed"]``. An explicit ``seeds`` list replaces both.

        ``cases`` takes ready-made cases instead, such as your own data cut
        with ``timegym.cases_from_series``: each is forecast as given and
        nothing is generated, so it cannot be combined with what to forecast,
        ``seeds``, ``seed``, ``instances`` or the scorecard's settings. A
        case's manifest needs no ``kind`` or ``seed``; without them it is
        labelled ``case`` and has no seed. Cases with the same ``kind`` share a
        row of the plots. Real data has no answer key, so such a run has no
        scorecard.

        The result holds every case's metrics and output checks:
        ``result.scorecard`` (a ``Scorecard``: ``result.scorecard.plot()``,
        ``print(result.scorecard)``), ``result.assert_passed()``,
        ``result.to_json(path)``, ``result.checks``, ``result.report`` and
        ``result.plot_errors()``. The series, answer keys and forecasts are
        dropped once every case is measured, unless ``keep_data=True``: then
        ``result.cases`` holds them and ``result.plot_forecasts()`` can draw
        them. The scorecard keeps what its picture draws either way.

        ``attainable`` and ``interval_level`` are the scorecard's own settings;
        its title is the pipeline's ``name``, or the model's when it has none.
        ``interval_level`` says how cautious the interval around each score
        is: 0.95 by default, 0.99 gives a wider one. ``attainable`` in its
        table is what the pattern's own model family, fitted to each history,
        scores on 200 fresh series of the row. The default grid's values are
        stored. Off the default grid (another noise level, ``history_length``
        or ``horizon``) the column is NaN unless ``attainable=True``, which
        simulates the missing values once per session: about 3 to 5 seconds
        for each autoregressive or random-walk cell and well under a second for
        the others. A pattern of your own has no stored values: with
        ``Pattern.attainable_by`` and ``attainable=True`` its attainable score
        is simulated in the same way, otherwise it is NaN.

        ``metrics`` records more metrics in every case, as in
        ``timegym.diagnostics.evaluate_forecast``: names of functions in
        ``timegym.metrics`` such as ``"brier"``, your own functions, or a
        dictionary from name to function. ``result.metadata["metrics"]`` lists
        them, and says which replay can compute again. ``scores``, their old
        name, still works and warns.

        ``checks`` adds output checks of your own to every case, as in
        ``evaluate_forecast``: functions such as ``timegym.checks.within(0,
        None)``, or a dictionary from name to function. They appear in
        ``result.checks`` and ``assert_passed`` like the built-in checks.
        ``result.metadata["checks"]`` lists them with their titles, and says
        which replay can run again. ``timegym.checks.dependence()`` among them
        checks that the sample paths of every case move together as its answer
        key says; its row in ``result.checks`` is "dependence", and
        ``result.metadata["diagnostic_settings"]`` records its settings for
        replay. ``check_dependence``, ``n_calibration``, ``alpha`` and
        ``dependence_seed_offset``, its old form, still work and warn.
        """
        if not isinstance(keep_data, bool):
            raise TypeError("keep_data must be True or False")
        settings, checks = _dependence_request("Pipeline.run", checks, old_arguments)
        return self._run(
            scenarios,
            seeds,
            seed=seed,
            instances=instances,
            cases=cases,
            noise_levels=noise_levels,
            history_length=history_length,
            horizon=horizon,
            keep_data=keep_data,
            attainable=attainable,
            interval_level=interval_level,
            metrics=metrics,
            checks=checks,
            **settings,
            default_instances=10,
        )

    def _run(
        self,
        scenarios,
        seeds,
        *,
        seed,
        instances,
        cases,
        keep_data,
        metrics,
        checks,
        check_dependence,
        n_calibration,
        alpha,
        dependence_seed_offset,
        default_instances,
        noise_levels=None,
        history_length=None,
        horizon=None,
        attainable=False,
        interval_level=None,
        old_scenarios=False,
        make_card=True,
    ):
        """``run`` with its defaults spelled out.

        ``old_scenarios`` keeps the five kinds ``test`` drew when given none, and
        ``make_card=False`` skips the scorecard for callers that only want the report.
        """
        from timegym.scorecard import (
            _card_from_run,
            _interval_level,
            _model_title,
            _run_rows,
        )

        self._ask_for_a_model()
        if interval_level is not None:
            _interval_level(interval_level)  # refused before any series is drawn
        if cases is not None:
            if (
                scenarios is not None
                or seeds is not None
                or seed != 0
                or instances is not None
            ):
                raise ValueError(
                    "Pass either cases=[...] or scenarios with seeds, seed or "
                    "instances, not both"
                )
            given = [
                name
                for name, value in (
                    ("noise_levels", noise_levels),
                    ("history_length", history_length),
                    ("horizon", horizon),
                    ("interval_level", interval_level),
                )
                if value is not None
            ]
            given += ["attainable"] if attainable else []
            if given:
                raise ValueError(
                    f"{', '.join(given)} {'belongs' if len(given) == 1 else 'belong'} to the "
                    "scorecard, and cases=[...] have none: "
                    "nobody knows the answer key of real data"
                )
        if self.steps:
            SklearnForecaster(self.steps, self.window_length)
        settings = diagnostic_settings(
            check_dependence=check_dependence,
            n_calibration=n_calibration,
            alpha=alpha,
            dependence_seed_offset=dependence_seed_offset,
        )
        config = self.to_config()
        name = getattr(self, "name", None)  # a pipeline pickled before names has none
        metadata = {
            **runtime_provenance(),
            "model": self._model_name(),
            **({} if name is None else {"name": name}),
            "window_length": self.window_length,
            "reduction": self.reduction,
            "target_transform": config["target_transform"],
            "pipeline_config": config,
            "diagnostic_settings": settings,
        }
        if metrics is not None:
            # Read once, so each request warns once, not once per case.
            metrics = _metric_requests(metrics)
            metadata["metrics"] = _describe_metrics(
                metrics
            )  # refuses a bad request before anything runs
        if checks is not None:
            checks = _check_requests(checks)
            metadata["checks"] = _describe_checks(checks)
        if cases is not None:
            results = _evaluate_ready_made(
                cases,
                lambda position, case: self.predict(
                    case.task.history, case.task.future_index
                ),
                settings,
                metrics,
                checks,
            )
            run = ForecastRun(cases=results, metadata=metadata)
            return run if keep_data else run._drop_data()
        seeds, seeding = _instance_seeds(seeds, seed, instances, default_instances)
        if old_scenarios and scenarios is None:
            scenarios = default_scenarios()
        cells, grid = _run_rows(scenarios, noise_levels, history_length, horizon)
        if not seeds:
            raise ValueError("Provide at least one scenario and one seed")
        results = []
        for scenario_index, cell in enumerate(cells):
            scenario = cell.scenario
            for seed_index, case_seed in enumerate(seeds):
                case = scenario.generate(seed=case_seed)
                forecast, result = _evaluate_case(
                    case,
                    lambda c: self.predict(c.task.history, c.task.future_index),
                    scenario.kind,
                    int(case_seed),
                    int(case_seed) + dependence_seed_offset,
                    settings,
                    metrics,
                    checks,
                )
                results.append(
                    EvaluatedCase(
                        case=case,
                        forecast=forecast,
                        result=result,
                        scenario_index=scenario_index,
                        seed_index=seed_index,
                    )
                )
        run = ForecastRun(
            cases=results,
            metadata={**metadata, **(seeding or {})},
            titles=[f"{cell.title} · {cell.noise}" for cell in cells] if grid else [],
        )
        if make_card:
            run._set_scorecard(
                lambda: _card_from_run(
                    run,
                    cells,
                    title=name or _model_title(self),
                    seeds=seeds,
                    attainable=attainable,
                    interval_level=interval_level,
                ),
                now=not keep_data,
            )
        return run if keep_data else run._drop_data()

    @_renamed_keywords(scores="metrics")
    def test(
        self,
        scenarios=None,
        seeds=None,
        *,
        seed=0,
        instances=None,
        cases=None,
        metrics=None,
        checks=None,
        **old_arguments,
    ):
        """Evaluate each scenario on each instance and return a TestReport; use ``run`` instead.

        ``pipeline.test(...)`` is ``pipeline.run(...).report`` with the old
        defaults: with no scenarios it draws ``default_scenarios()``, the five
        core kinds, 3 times each. It warns and will be removed in a later
        release; ``run`` returns the same report as ``result.report``, with
        ``result.assert_passed()``, ``result.to_json()`` and the scorecard.
        """
        _warn_deprecated(_TEST_MOVED)
        settings, checks = _dependence_request("Pipeline.test", checks, old_arguments)
        return self._run(
            scenarios,
            seeds,
            seed=seed,
            instances=instances,
            cases=cases,
            keep_data=False,
            metrics=metrics,
            checks=checks,
            **settings,
            default_instances=3,
            old_scenarios=True,
            make_card=False,
        ).report

    @_renamed_keywords(context_length="history_length")
    def scorecard(
        self,
        patterns=None,
        *,
        noise_levels=2,
        instances=10,
        seed=0,
        history_length=120,
        horizon=24,
        title=None,
        attainable=False,
        interval_level=0.95,
    ):
        """Score the model on a grid of patterns and noise levels and return a Scorecard; use ``run`` instead.

        ``pipeline.scorecard(...)`` is ``pipeline.run(..., keep_data=True).scorecard``
        with the same arguments, the patterns first: ``card.run`` keeps every
        series and forecast, as it always did. It warns and will be removed
        in a later release. See ``run`` for the settings and ``Scorecard`` for
        what the card holds. ``title`` heads the card in place of the
        pipeline's name. ``context_length`` is the old name of
        ``history_length``; it still works and warns.
        """
        from timegym.scorecard import _scorecard

        _warn_deprecated(_SCORECARD_MOVED)
        return _scorecard(
            self,
            patterns,
            noise_levels=noise_levels,
            instances=instances,
            seed=seed,
            history_length=history_length,
            horizon=horizon,
            title=title,
            attainable=attainable,
            interval_level=interval_level,
        )

    def plot_tests(
        self,
        scenarios=None,
        seeds=None,
        *,
        seed=0,
        instances=None,
        show_quantiles=False,
        figsize=None,
        history=None,
        **diagnostic_settings,
    ):
        """Fit a display suite and return its forecast matrix Figure.

        Display defaults use 240 steps of history and 80 to forecast;
        ``test`` and ``run`` keep their defaults of 120 steps of history and 12
        steps. To make several figures from the same fits, use ``run`` and its
        plot methods.
        """
        _deprecated(
            "Pipeline.plot_tests",
            "use Pipeline.run(..., keep_data=True).plot_forecasts() instead",
        )
        if scenarios is None:
            scenarios = default_scenarios(history_length=240, horizon=80)
        return self._run(
            scenarios,
            seeds,
            seed=seed,
            instances=instances,
            cases=None,
            keep_data=True,
            metrics=None,
            checks=None,
            default_instances=3,
            **_old_settings(diagnostic_settings),
        ).plot_forecasts(
            show_quantiles=show_quantiles, figsize=figsize, history=history
        )

    def plot_errors(
        self,
        scenarios=None,
        seeds=None,
        *,
        seed=0,
        instances=None,
        metric="avoidable_mse",
        bins=None,
        missing="raise",
        figsize=None,
        **diagnostic_settings,
    ):
        """Fit once per requested case and plot the retained distribution of one metric.

        This convenience call draws 20 instances by default. Use an existing
        run's ``plot_errors`` method to inspect previously evaluated forecasts.
        """
        _deprecated(
            "Pipeline.plot_errors", "use Pipeline.run(...).plot_errors() instead"
        )
        if seeds is None and instances is None:
            instances = 20
        return self._run(
            scenarios,
            seeds,
            seed=seed,
            instances=instances,
            cases=None,
            keep_data=True,
            metrics=None,
            checks=None,
            default_instances=3,
            old_scenarios=True,
            **_old_settings(diagnostic_settings),
        ).plot_errors(metric=metric, bins=bins, missing=missing, figsize=figsize)


