def _without_tracebacks(value):
    if isinstance(value, dict):
        return {
            key: _without_tracebacks(item)
            for key, item in value.items()
            if key != "traceback"
        }
    if isinstance(value, list):
        return [_without_tracebacks(item) for item in value]
    return value


def _tracebacks(value, path=()):
    found = {}
    if isinstance(value, dict):
        for key, item in value.items():
            if key == "traceback":
                found[path + (key,)] = item
            else:
                found.update(_tracebacks(item, path + (key,)))
    elif isinstance(value, list):
        for index, item in enumerate(value):
            found.update(_tracebacks(item, path + (index,)))
    return found


def _replay_case(report: TestReport, case_index=0):
    """Replay one report case and compare regenerated metrics and diagnostics.

    The return value is a new TestReport. ``metadata['replay']`` records exact
    result equality excluding tracebacks, plus traceback and environment agreement.
    Metrics asked for by name from ``timegym.metrics`` are computed again; your
    own functions cannot be rebuilt from a report, so they are left out of the
    comparison and listed in ``metadata['replay']['not_recomputed']``.
    Checks made with ``timegym.checks.within`` run again; your own check
    functions are left out the same way and listed in
    ``metadata['replay']['checks_not_rerun']``.
    Replaying in a different environment is allowed and reported.
    """
    payload = report.to_dict()
    case_index = nonnegative_int(case_index, "case_index")
    if case_index >= len(report.cases):
        raise ValueError("case_index is outside the saved report")
    original = payload["cases"][case_index]
    saved_metadata = payload["metadata"]
    # A case saved by TimeGym 1.13.1 or earlier says context_length; read it as history_length.
    manifest = _current_manifest(original["manifest"])
    constructor_keys = (
        "kind",
        "history_length",
        "horizon",
        "parameters",
        "n_targets",
        "seed",
    )
    if any(key not in manifest for key in constructor_keys):
        raise ValueError(
            f"Case {case_index} was not drawn from a TimeGym scenario (for example, it came from "
            "your own data), so it cannot be drawn again and replayed"
        )
    if "pipeline_config" not in saved_metadata:
        raise ValueError(
            "This report has no pipeline configuration, for example because its forecasts "
            "were recorded earlier, so no model can be rebuilt to replay it"
        )
    pipeline = Pipeline.from_config(saved_metadata.get("pipeline_config"))
    settings = saved_metadata.get("diagnostic_settings")
    setting_keys = {
        "check_dependence",
        "n_calibration",
        "alpha",
        "dependence_seed_offset",
    }
    if not isinstance(settings, dict) or set(settings) != setting_keys:
        raise ValueError("Report diagnostic settings are absent or unsupported")
    settings = diagnostic_settings(**settings)
    if (
        type(manifest.get("schema_version")) is not int
        or manifest["schema_version"] != MANIFEST_SCHEMA_VERSION
    ):
        raise ValueError("Unsupported scenario manifest schema")
    if (
        original.get("seed") != manifest["seed"]
        or original.get("scenario") != manifest["kind"]
    ):
        raise ValueError("Case identity and scenario manifest disagree")
    scenario = Scenario(**{key: manifest[key] for key in constructor_keys})
    # Metrics asked for by name from timegym.metrics are computed again; your own are left out of the comparison.
    # A report saved by TimeGym 1.13.1 or earlier lists them under "scores".
    requested = saved_metadata.get("metrics", saved_metadata.get("scores"))
    metrics, not_recomputed = (
        (None, []) if requested is None else _rebuild_metrics(requested)
    )
    # The same for checks: within() runs again, your own functions are left out.
    requested_checks = saved_metadata.get("checks")
    checks, not_rerun = (
        (None, []) if requested_checks is None else _rebuild_checks(requested_checks)
    )
    regenerated = pipeline._run(
        [scenario],
        [manifest["seed"]],
        seed=0,
        instances=None,
        cases=None,
        keep_data=False,
        metrics=metrics,
        checks=checks,
        default_instances=3,
        make_card=False,
        **settings,
    ).report
    actual = regenerated.cases[0].to_dict()
    left_out = {"metric_" + name for name in not_recomputed} | {
        "check_" + name for name in not_rerun
    }
    original_metrics = {
        key: value
        for key, value in original.get("metrics", {}).items()
        if key not in not_recomputed
    }
    original_diagnostics = [
        item for item in original["diagnostics"] if item.get("name") not in left_out
    ]
    regenerated.metadata["replay"] = {
        "case_index": case_index,
        "metrics_match": actual["metrics"] == original_metrics,
        "diagnostics_match": _without_tracebacks(actual["diagnostics"])
        == _without_tracebacks(original_diagnostics),
        "traceback_match": _tracebacks(actual["diagnostics"])
        == _tracebacks(original_diagnostics),
        "manifest_match": _current_manifest(actual["manifest"]) == manifest,
        "source_matches": regenerated.metadata["source"]
        == saved_metadata.get("source"),
        "dependencies_match": regenerated.metadata["dependencies"]
        == saved_metadata.get("dependencies"),
        "python_matches": regenerated.metadata["python"]
        == saved_metadata.get("python"),
    }
    comparison = regenerated.metadata["replay"]
    if requested is not None:
        comparison["not_recomputed"] = not_recomputed
    if requested_checks is not None:
        comparison["checks_not_rerun"] = not_rerun
    comparison["reproduced"] = all(
        comparison[key]
        for key in ("metrics_match", "diagnostics_match", "manifest_match")
    )
    comparison["same_environment"] = all(
        comparison[key]
        for key in ("source_matches", "dependencies_match", "python_matches")
    )
    return regenerated


def replay_case(report: TestReport, case_index=0):
    """Replay one report case; the same as ``report.replay_case(case_index)``."""
    _deprecated(
        "timegym.pipeline.replay_case", "use report.replay_case(case_index) instead"
    )
    if not isinstance(report, TestReport):
        raise TypeError(
            "replay_case requires a TestReport; load saved data with TestReport.from_dict"
        )
    return _replay_case(report, case_index)
